package io.github.jackotom.hongguo.android;
import org.json.*;
import javax.net.ssl.*;
import java.net.*;
import java.io.*;
import java.lang.reflect.*;
import java.security.cert.Certificate;
import java.util.*;
import java.util.concurrent.*;

public final class AccountSyncLifecycleTest {
    static int checks,groups,failNext;static long revision;static CountDownLatch blockEntered,blockRelease;static String blockPath="";
    static final Map<String,Long> watermarks=new HashMap<>();static final Map<String,String> deviceByHost=new HashMap<>();static boolean sharedBackend;
    static final Map<String,Map<String,JSONObject>> cloud=new HashMap<>();static final List<String> requests=new ArrayList<>();
    interface Checked {void run()throws Exception;}
    static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    static void group(String name,Checked run)throws Exception{reset();run.run();groups++;System.out.println("PASS "+name);}
    static void waitFor(java.util.function.BooleanSupplier condition)throws Exception{long end=System.currentTimeMillis()+6000;while(!condition.getAsBoolean()&&System.currentTimeMillis()<end)Thread.sleep(10);check(condition.getAsBoolean(),"asynchronous condition completed");}
    static boolean idle(AccountSync sync){try{return !sync.getAccount().getBoolean("syncing")&&sync.getAccount().getLong("lastSyncAt")>0;}catch(Exception e){return false;}}
    static JSONObject credentials(String server,String user)throws Exception{return new JSONObject().put("serverUrl",server).put("username",user).put("password","test-password-1234").put("deviceName","fixture");}
    static void stop()throws Exception {Field f=AccountSync.class.getDeclaredField("instance");f.setAccessible(true);Object object=f.get(null);if(object!=null)for(String name:new String[]{"executor","diskExecutor"}){Field ex=AccountSync.class.getDeclaredField(name);ex.setAccessible(true);ScheduledThreadPoolExecutor executor=(ScheduledThreadPoolExecutor)ex.get(object);executor.shutdownNow();executor.awaitTermination(3,TimeUnit.SECONDS);}f.set(null,null);LibraryStore.setHistoryFactory(null);}
    static void reset()throws Exception {if(blockRelease!=null)blockRelease.countDown();stop();cloud.clear();watermarks.clear();deviceByHost.clear();sharedBackend=false;requests.clear();failNext=0;revision=0;blockPath="";blockEntered=null;blockRelease=null;}
    static SearchHistoryStoreTest.Prefs prefs(SearchHistoryStoreTest.AppContext c){return (SearchHistoryStoreTest.Prefs)c.getSharedPreferences("hongguo_accounts_v1",0);}
    static class Connection extends HttpsURLConnection {
        ByteArrayOutputStream out=new ByteArrayOutputStream();String response="{}";int status=200;boolean prepared;
        Connection(URL url){super(url);}public void disconnect(){}public boolean usingProxy(){return false;}public void connect(){}public String getCipherSuite(){return "fixture";}public Certificate[]getLocalCertificates(){return null;}public Certificate[]getServerCertificates(){return null;}public OutputStream getOutputStream(){return out;}public long getContentLengthLong(){return response.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;}
        public String getHeaderField(String name){return name.equalsIgnoreCase("Retry-After")?"2":null;}
        public int getResponseCode()throws IOException{
            if(prepared)return status;prepared=true;
            try {
                String path=url.getPath(),host=url.getHost(),auth=getRequestProperty("Authorization");requests.add(host+path+":"+(auth==null?"anonymous":"bearer"));
                if(path.equals(blockPath)){blockPath="";blockEntered.countDown();blockRelease.await(4,TimeUnit.SECONDS);}
                if(failNext!=0){status=failNext;failNext=0;return status;}
                if(path.equals("/v1/auth/login")){JSONObject body=new JSONObject(out.toString("UTF-8"));String user=body.getString("username");response=new JSONObject().put("token",user.equals("bob")?"b".repeat(64):"a".repeat(64)).put("expiresAt","2030-01-01T00:00:00Z").put("user",new JSONObject().put("id",user).put("username",user)).toString();return 200;}
                String user=auth!=null&&auth.contains("bbbb")?"bob":"alice",scope=(sharedBackend?"sync.example":host)+":"+user;Map<String,JSONObject> rows=cloud.computeIfAbsent(scope,k->new HashMap<>());
                if(path.equals("/v1/auth/logout")){status=204;return status;}
                if(path.equals("/v1/history/sync")){JSONObject body=new JSONObject(out.toString("UTF-8"));String device=body.getString("deviceId");deviceByHost.put(host,device);JSONArray results=new JSONArray(),mutations=body.getJSONArray("mutations");
                for(int j=0;j<mutations.length();j++){long sequence=mutations.getJSONObject(j).getLong("sequence");String key=scope+":"+device;if(sequence<=watermarks.getOrDefault(key,0L)){status=409;return status;}watermarks.put(key,sequence);}
                for(int i=0;i<mutations.length();i++){JSONObject m=mutations.getJSONObject(i),r=m.getJSONObject("record");String sid=r.getString("seriesId");JSONObject existing=rows.get(sid);boolean ok=(existing==null?0:existing.getLong("revision"))==m.getLong("baseRevision");if(ok){r.put("revision",++revision).put("updatedAt",System.currentTimeMillis());rows.put(sid,r);}results.put(new JSONObject().put("mutationId",m.getString("mutationId")).put("status",ok?"applied":"conflict").put("record",ok?r:existing));}response=new JSONObject().put("results",results).toString();return 200;}
                if(path.equals("/v1/history")){long cursor=Long.parseLong(url.getQuery().split("[=&]")[1]);JSONArray records=new JSONArray();long next=cursor;for(JSONObject row:rows.values())if(row.getLong("revision")>cursor){records.put(row);next=Math.max(next,row.getLong("revision"));}response=new JSONObject().put("records",records).put("cursor",next).put("hasMore",false).toString();return 200;}
                status=404;return status;
            }catch(Exception e){throw new IOException(e);}
        }
        public InputStream getInputStream()throws IOException{getResponseCode();return new ByteArrayInputStream(response.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    }
    public static void main(String[]args)throws Exception {
        URL.setURLStreamHandlerFactory(protocol->protocol.equals("https")?new URLStreamHandler(){protected URLConnection openConnection(URL url){return new Connection(url);}}:null);
        try {
            group("startup is offline and guest remains playable",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);check(requests.isEmpty()&&!sync.getAccount().getBoolean("authenticated"),"initialization never accesses network");JSONObject row=HistorySyncStateTest.row("123456",1,100);new LibraryStore(c).history(row,row,100);check(new LibraryStore(c).position(row,row)==100,"guest history works without account");});
            group("login metadata excludes credentials and account scope does not import guest",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);JSONObject row=HistorySyncStateTest.row("123456",1,100);LibraryStore guest=new LibraryStore(c);guest.history(row,row,100);sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));JSONObject state=sync.getAccount();check(state.getBoolean("authenticated")&&state.getJSONObject("user").getString("username").equals("alice"),"safe authenticated profile");check(!state.toString().contains("a".repeat(64))&&!state.has("password")&&!state.has("token"),"no secret exposed to JS");check(new LibraryStore(c).library().getJSONArray("history").length()==0,"guest not silently uploaded");check(!prefs(c).getString("sealedToken","").contains("a".repeat(64)),"vault boundary receives ciphertext");check(!state.getBoolean("syncing"),"scheduled periodic timer is not a busy sync");});
            group("captured writers and disk restart retain per-account outbox",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));JSONObject row=HistorySyncStateTest.row("123456",1,500);new LibraryStore(c).history(row,row,500);sync.flush();waitFor(()->{try{return sync.getAccount().getInt("pendingCount")==0;}catch(Exception e){return false;}});stop();AccountSync restarted=AccountSync.init(c.reopen());check(restarted.getAccount().getBoolean("authenticated")&&new LibraryStore(c.reopen()).position(row,row)==500,"account local progress and encrypted session survive new process");});
            group("401 keeps local account records and outbox until relogin",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));JSONObject row=HistorySyncStateTest.row("123456",1,600);new LibraryStore(c).history(row,row,600);failNext=401;sync.syncNow();waitFor(()->{try{return sync.getAccount().getBoolean("loginRequired");}catch(Exception e){return false;}});check(!sync.getAccount().getBoolean("authenticated")&&sync.getAccount().getInt("pendingCount")==1,"expired auth retains pending rows");check(new LibraryStore(c).position(row,row)==600&&!prefs(c).getAll().containsKey("sealedToken"),"account scope survives auth expiry and token is cleared");});
            group("logout commit failure preserves identity and restores preference memory",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));Map<String,?>before=prefs(c).getAll();prefs(c).failCommits=1;boolean rejected=false;try{sync.logout();}catch(Exception expected){rejected=true;}check(rejected&&sync.getAccount().getBoolean("authenticated"),"failed disk logout is not successful logout");check(prefs(c).getAll().equals(before),"failed Android commit restores credential memory");});
            group("failed login persistence does not contaminate later disk commits",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);Map<String,?>before=prefs(c).getAll();prefs(c).failCommits=1;boolean rejected=false;try{sync.login(credentials("https://sync.example","alice"));}catch(Exception expected){rejected=true;}check(rejected&&!sync.getAccount().getBoolean("authenticated")&&prefs(c).getAll().equals(before),"failed login restores old selection/ciphertext");});
            group("logout ignores already-running old response and remembers server",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));cloud.get("sync.example:alice").put("123456",HistorySyncStateTest.remote("123456",8,8000,++revision));blockPath="/v1/history";blockEntered=new CountDownLatch(1);blockRelease=new CountDownLatch(1);sync.syncNow();check(blockEntered.await(2,TimeUnit.SECONDS),"old pull in flight");sync.logout();blockRelease.countDown();Thread.sleep(100);check(!sync.getAccount().getBoolean("authenticated")&&new LibraryStore(c).library().getJSONArray("history").length()==0,"late old account response cannot become guest history");stop();AccountSync reopened=AccountSync.init(c.reopen());check(reopened.getAccount().getString("serverUrl").equals("https://sync.example")&&!reopened.getAccount().getBoolean("authenticated"),"logged-out server retained after restart");});
            group("explicit guest import preserves originals and skips existing account progress",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);JSONObject one=HistorySyncStateTest.row("123456",2,200),two=HistorySyncStateTest.row("654321",3,300);LibraryStore guest=new LibraryStore(c);guest.history(one,one,200);guest.history(two,two,300);String before=c.prefs().getString("history","");sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));JSONObject result=sync.importGuestHistory();check(result.getInt("importedCount")==2&&c.prefs().getString("history","").equals(before),"explicit import queues without editing guest source");JSONObject again=sync.importGuestHistory();check(again.getInt("importedCount")==0&&again.getInt("skippedCount")==2,"repeat import cannot overwrite existing progress");});
            group("HTTPS redirects are rejected and never forwarded",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);failNext=302;boolean rejected=false;try{sync.login(credentials("https://sync.example","alice"));}catch(Exception expected){rejected=true;}check(rejected&&!sync.getAccount().getBoolean("authenticated")&&requests.size()==1,"redirect creates no second request or token transfer");});
            group("listener removal only removes the matching Activity callback",()->{AccountSync sync=AccountSync.init(new SearchHistoryStoreTest.AppContext());Runnable old=()->{},current=()->{};sync.setListener(old);sync.setListener(current);sync.clearListener(old);Field f=AccountSync.class.getDeclaredField("listener");f.setAccessible(true);check(f.get(sync)==current,"old destroy cannot remove new Activity listener");sync.clearListener(current);check(f.get(sync)==null,"matching Activity listener released");});
            group("periodic sync remains single queued timer and honors server retry",()->{AccountSync sync=AccountSync.init(new SearchHistoryStoreTest.AppContext());sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));Field timer=AccountSync.class.getDeclaredField("scheduled");timer.setAccessible(true);ScheduledFuture<?> scheduled=(ScheduledFuture<?>)timer.get(sync);check(scheduled!=null&&scheduled.getDelay(TimeUnit.MILLISECONDS)>0&&!sync.getAccount().getBoolean("syncing"),"idle pulls continue without permanently busy UI");failNext=429;sync.syncNow();waitFor(()->{try{return !sync.getAccount().getString("error").isEmpty()&&!sync.getAccount().getBoolean("syncing");}catch(Exception e){return false;}});int count=requests.size();for(int i=0;i<20;i++)sync.syncNow();Thread.sleep(100);check(requests.size()==count,"manual retries respect Retry-After/backoff");Field executor=AccountSync.class.getDeclaredField("executor");executor.setAccessible(true);check(((ScheduledThreadPoolExecutor)executor.get(sync)).getQueue().size()==1,"no overlapping retry backlog");});
            group("corrupted encrypted token retains account history and asks to relogin",()->{SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));JSONObject row=HistorySyncStateTest.row("123456",1,123);new LibraryStore(c).history(row,row,123);sync.flush();waitFor(()->{try{return sync.getAccount().getInt("pendingCount")==0;}catch(Exception e){return false;}});prefs(c).edit().putString("sealedToken","corrupt-ciphertext").commit();stop();AccountSync reopened=AccountSync.init(c.reopen());check(reopened.getAccount().getBoolean("loginRequired")&&!reopened.getAccount().getBoolean("authenticated")&&new LibraryStore(c.reopen()).position(row,row)==123,"Keystore/decryption failure is login-required, never guest migration or crash");});
            group("same account behind a changed server origin gets independent sequence identity",()->{
                sharedBackend=true;SearchHistoryStoreTest.AppContext c=new SearchHistoryStoreTest.AppContext();AccountSync sync=AccountSync.init(c);
                sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));JSONObject first=HistorySyncStateTest.row("123456",1,123);new LibraryStore(c).history(first,first,123);sync.flush();waitFor(()->{try{return sync.getAccount().getInt("pendingCount")==0;}catch(Exception e){return false;}});
                String oldDevice=deviceByHost.get("sync.example");sync.logout();sync.login(credentials("https://alias.example","alice"));waitFor(()->idle(sync));JSONObject second=HistorySyncStateTest.row("654321",1,456);new LibraryStore(c).history(second,second,456);sync.flush();waitFor(()->{try{return sync.getAccount().getInt("pendingCount")==0;}catch(Exception e){return false;}});
                String newDevice=deviceByHost.get("alias.example");check(oldDevice!=null&&newDevice!=null&&!oldDevice.equals(newDevice),"origin-scoped counter uses a distinct wire device ID even for same user/database");check(cloud.get("sync.example:alice").size()==2,"new-origin sequence1 reaches same backend without obsolete/mutation-reused failure");
                sync.logout();sync.login(credentials("https://sync.example","alice"));waitFor(()->idle(sync));new LibraryStore(c).history(first,first,789);sync.flush();waitFor(()->{try{return sync.getAccount().getInt("pendingCount")==0;}catch(Exception e){return false;}});check(deviceByHost.get("sync.example").equals(oldDevice),"returning to original scope keeps stable device identity and monotonic counter");
            });
            System.out.println("ACCOUNT_SYNC_LIFECYCLE_OK groups="+groups+" checks="+checks+" transport=mock-HTTPS vault=test-double realAndroidKeystore=not_run");
        }finally{reset();}
    }
}
